def bounded_runs(line):
    res=set(); n=len(line); i=0
    while i<n:
        if line[i]==4:
            j=i
            while j<n and line[j]==4: j+=1
            if i>0 and j<n and line[i-1]==9 and line[j]==9:
                res.update(range(i,j))
            i=j
        else: i+=1
    return res
