prog='''def transform(grid):
    """Minority color draws broken rectangle frame(s); fill frame-line gaps
    (bbox perimeter + interior pane-divider rows/cols) with 2."""
    from collections import Counter
    cnt = Counter(x for row in grid for x in row)
    mk = min(cnt, key=cnt.get)
    H, W = len(grid), len(grid[0])
    cells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == mk]
    r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
    o = [row[:] for row in grid]

    def fill(r, c):
        if o[r][c] != mk:
            o[r][c] = 2

    for r in range(r0, r1 + 1):
        fill(r, c0); fill(r, c1)
    for c in range(c0, c1 + 1):
        fill(r0, c); fill(r1, c)

    # interior divider lines: full-span rows/cols whose panes stay marker-free
    def clean(ra, rb, ca, cb):
        return all(grid[r][c] != mk
                   for r in range(ra + 1, rb) for c in range(ca + 1, cb))
    rdiv = []
    for r in range(r0 + 1, r1):
        if grid[r][c0] == mk and grid[r][c1] == mk and clean(r0, r, c0, c1) and clean(r, r1, c0, c1):
            rdiv.append(r)
    cdiv = []
    for c in range(c0 + 1, c1):
        if grid[r0][c] == mk and grid[r1][c] == mk and clean(r0, r1, c0, c) and clean(r0, r1, c, c1):
            cdiv.append(c)
    for r in rdiv:
        for c in range(c0, c1 + 1):
            fill(r, c)
    for c in cdiv:
        for r in range(r0, r1 + 1):
            fill(r, c)
    return o
'''
